use kino_core::{color::exposure,effects::Frame};
#[test]fn exposure_percentiles_signed_hdr(){let f=Frame{w:5,h:1,d:[-0.25,0.,0.18,1.,4.].iter().flat_map(|v|[*v,*v,*v,1.]).collect()};let v=exposure::analyze(&f,0,100.,0.18,200.).unwrap();assert!((v["luminance_quantiles"][4].as_f64().unwrap()-0.18).abs()<1e-6);assert!((v["declared_nits_quantiles"][8].as_f64().unwrap()-400.).abs()<1e-6);assert_eq!(v["negative_rgb_pixels"],1);assert_eq!(v["above_declared_peak_rgb_pixels"],1);assert_eq!(v["nonpositive_luminance_pixels"],2);let n:u64=v["stop_histogram"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).sum();assert_eq!(n,3)}
#[test]fn exposure_alpha_and_invalid(){let f=Frame{w:3,h:1,d:vec![1.,1.,1.,0.,4.,4.,4.,0.5,f32::NAN,0.,0.,1.]};let v=exposure::analyze(&f,3,100.,0.18,1000.).unwrap();assert_eq!(v["visible_pixels"],1);assert_eq!(v["invalid_pixels"],1);assert_eq!(v["transparent_pixels"],1);assert!((v["alpha_weighted_mean_luminance"].as_f64().unwrap()-4.).abs()<1e-10);}
#[test]fn exposure_hostile_domain(){let f=Frame{w:0,h:0,d:vec![]};assert!(exposure::analyze(&f,8,100.,0.18,1000.).is_err());assert!(exposure::analyze(&f,0,0.,0.18,1000.).is_err());assert!(exposure::analyze(&f,0,100.,0.,1000.).is_err());assert!(exposure::analyze(&f,0,100.,0.18,f64::NAN).is_err());let v=exposure::analyze(&f,0,100.,0.18,1000.).unwrap();assert!(v["luminance_quantiles"][0].is_null());}
#[test]fn falsecolor_palette_boundaries(){let f=Frame{w:5,h:1,d:[-1.,0.18/128.,0.18,0.18*16.,0.18*128.].iter().flat_map(|v|[*v,*v,*v,1.]).collect()};let q=exposure::false_color(&f,0,0.18).unwrap();assert_eq!(&q.d[0..3],&[0.1,0.,0.2]);assert_eq!(&q.d[8..11],&[0.1,0.65,0.1]);assert_eq!(&q.d[16..19],&[1.,0.,0.]);assert!(exposure::false_color(&f,99,0.18).is_err());}
#[test]fn sequence_sampling_boundaries(){use kino_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.18,0.18,0.18],"start":0,"duration":2})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();let v=dispatch(&mut s,"analyze_exposure_sequence",&json!({"start":0,"end":2,"samples":4})).unwrap();assert_eq!(v["samples"][3]["time"],1.5);assert_eq!(v["threshold_events"].as_array().unwrap().len(),0);for a in [json!({"start":2,"end":1}),json!({"start":0,"end":2,"samples":121}),json!({"start":0,"end":3})]{assert!(dispatch(&mut s,"analyze_exposure_sequence",&a).is_err());}}
